{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver approaches the ruined city gates.",
      "visual_description": "A massive iron gate, rusted and half-open, with tattered royal banners hanging above. The glass diver stands before it, his helmet reflecting the crumbling towers.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the Cartographer unfolds a map of the city.",
      "visual_description": "Mara kneels on a broken cobblestone street, ink-stained fingers tracing a parchment map. Her brass compass glints in the dim light.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning from a window ledge.",
      "visual_description": "An oil lamp perched on a cracked windowsill, its single flame-eye glowing amber. The glass diver looks up, listening.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "A small metal fox with a key-wind tail scurries over broken stones, its blue glass eyes scanning for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The sleeping tax collector dozes at a ruined checkpoint.",
      "visual_description": "A ledger book as a pillow, stamped papers stuck to his sleeves. He snores softly amid collapsed barrels.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara spots a cursed tower on the map.",
      "visual_description": "Mara points to a sketch of a crooked spire on her map, her expression grim. The glass diver peers over her shoulder.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The oracle lamp warns of rumors of dragons in the tower.",
      "visual_description": "The lamp's flame-eye burns brighter, casting dancing shadows on a wall. It flickers a shape like wings.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The tin fox discovers a magic door hidden behind a collapsed wall.",
      "visual_description": "The fox nudges aside rubble with its metal snout, revealing a door covered in glowing runes.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver swims through the mirror of the magic door.",
      "visual_description": "The glass diver presses his hand to the door's surface, which ripples like water. He steps through, his coat reflecting shattered city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Inside the cursed tower, Mara reads a hidden passage.",
      "visual_description": "Mara holds her compass up, the needle spinning. She traces a faint line on the wall, revealing a secret stair.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The sleeping tax collector wakes briefly, mumbling a clue.",
      "visual_description": "He stirs, mumbling about a 'bridge key' before rolling over, a stamped paper falling from his sleeve.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox finds the bridge key in a dead fountain.",
      "visual_description": "The fox's blue eyes reflect off a dry fountain basin. It digs a rusted key from the silt with its paws.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The oracle lamp warns of an armored patrol approaching.",
      "visual_description": "The lamp's flame-eye dims and flares. Through a broken window, distant figures in armor march among the ruins.",
      "characters": ["oracle_lamp", "glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver uses a mirror shard to blind the patrol.",
      "visual_description": "The glass diver holds up a shard, catching a ray of light and reflecting it into the patrol's eyes, causing them to stumble.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The group reunites at the bridge gate.",
      "visual_description": "Glass diver, Mara, tin fox, and oracle lamp gather before a portcullis. The sleeping tax collector is carried by the fox.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge key unlocks the gate.",
      "visual_description": "The tin fox inserts the rusted key into the gate's lock. Gears grind, and the portcullis creaks upward.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The group escapes across the crumbling bridge.",
      "visual_description": "A stone bridge spans a chasm, its edges crumbling. The group hurries across, the glass diver's coat flapping, as the tower collapses behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "On the far side, the oracle lamp goes quiet.",
      "visual_description": "The group stands on safe ground. The oracle lamp's flame-eye dims to a normal flame. The glass diver removes his helmet, breathing fresh air.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

